/** 몬스터 ID(npc_XXXXX) → 드롭 목록 조회 */
export function getMonsterDrops(monsterId: string): DropEntry[] {
  const npcId = parseInt(monsterId.replace('npc_', ''), 10);
  return MONSTER_DROPS[npcId] ?? [];
}
